def game_score(points: str) -> str:
    a_points = 0
    b_points = 0

    for point in points:
        # Check if someone has already won
        if a_points >= 4 and a_points > b_points:
            return "Game A"
        if b_points >= 4 and b_points > a_points:
            return "Game B"

        # Award the point
        if point == 'A':
            a_points += 1
        elif point == 'B':
            b_points += 1

    # Check for winner after all points
    if a_points >= 4 and a_points > b_points:
        return "Game A"
    if b_points >= 4 and b_points > a_points:
        return "Game B"

    # Convert points to tennis score
    score_map = {0: '0', 1: '15', 2: '30', 3: '40'}

    # Handle 40-40 and beyond (deuce situation)
    if a_points >= 3 and b_points >= 3:
        if a_points == b_points:
            return "40-40"
        # One player is ahead at deuce
        if a_points > b_points:
            return "40-40"  # This shouldn't happen given the win conditions above
        else:
            return "40-40"  # This shouldn't happen given the win conditions above

    # Normal scoring
    a_score = score_map.get(a_points, '40')
    b_score = score_map.get(b_points, '40')

    return f"{a_score}-{b_score}"

